CREATE TABLE IF NOT EXISTS eir_cancellation_orders (
  id BIGSERIAL PRIMARY KEY,
  row_key VARCHAR(255) UNIQUE,
  upload_id VARCHAR(50),
  file_name VARCHAR(255),
  stt_file VARCHAR(50),
  depot VARCHAR(20) NOT NULL,
  hang_tau VARCHAR(20) NOT NULL,
  ngay_huy_don TIMESTAMP WITHOUT TIME ZONE NOT NULL,
  ngay_duoc_duyet TIMESTAMP WITHOUT TIME ZONE,
  so_booking VARCHAR(100),
  so_container VARCHAR(100),
  loai_container VARCHAR(100),
  loai_don_hang VARCHAR(10),
  size_teus NUMERIC(4, 2) DEFAULT 0,
  trang_thai_don_hang VARCHAR(50) DEFAULT 'Chưa xác định',
  trang_thai_kich_hoat VARCHAR(50) DEFAULT 'Chưa kích hoạt',
  thoi_gian_kich_hoat TIMESTAMP WITHOUT TIME ZONE,
  ly_do_huy TEXT,
  ly_do_tu_choi TEXT,
  ly_do_huy_check TEXT,
  ten_tai_xe VARCHAR(150),
  sdt_tai_xe VARCHAR(50),
  ten_nha_xe VARCHAR(255),
  sdt_nha_xe VARCHAR(50),
  file_nguon VARCHAR(255),
  nguoi_tao VARCHAR(150),
  created_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);


